INSERT INTO public.modules (slug, code, track_id, title, title_ar, summary, summary_ar, external_url, position) VALUES ('sonoff-device-specific-mastery', 'M14', 'sonoff-installer-certification', 'SONOFF Device-Specific Mastery', 'إتقان أجهزة SONOFF المحددة', 'Hands-on installation and configuration for specific device categories: smart wall sockets, Fusion-series switches, dimmers, air quality sensors, smart thermostats, Zigbee coordinator flashing, and Apple HomeKit integration.', 'التركيب والإعداد العملي لفئات أجهزة محددة: المقابس الذكية، مفاتيح سلسلة Fusion، مفاتيح التعتيم، حساسات جودة الهواء، الترموستات الذكي، برمجة منسق Zigbee، والدمج مع Apple HomeKit.', NULL, 14);
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Smart Wall Sockets & Fusion Series Switches: Retrofit Wiring', 'المقابس الذكية ومفاتيح سلسلة Fusion: التوصيل في التركيبات القائمة', 'Retrofitting a smart wall socket or a Fusion-series multi-gang switch into an existing enclosure starts with a box-depth and wiring check: confirm there''s enough clearance for the smart module, identify live, neutral, and load conductors before disconnecting anything, and label each wire as it''s removed. For 2-gang and multi-gang installs, keep each gang''s load isolated during testing so a fault on one channel doesn''t get mistaken for a wiring error on another. Always de-energize the circuit at the breaker before opening the enclosure, and re-verify with a non-contact voltage tester before touching any conductor.', 'تركيب مقبس ذكي أو مفتاح متعدد المفاتيح من سلسلة Fusion في علبة قائمة يبدأ بفحص عمق العلبة والتوصيلات: تأكد من وجود مساحة كافية للوحدة الذكية، وحدد أسلاك الحي والمحايد والحمل قبل فصل أي شيء، وضع علامة على كل سلك عند إزالته. في التركيبات ثنائية أو متعددة المفاتيح، حافظ على عزل حمل كل مفتاح أثناء الاختبار حتى لا يُخلط عطل في قناة بخطأ توصيل في أخرى. اقطع التيار دائمًا من القاطع قبل فتح العلبة، وأعد التحقق بجهاز اختبار جهد بلا تلامس قبل لمس أي موصل.', 1 FROM public.modules WHERE slug = 'sonoff-device-specific-mastery';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Configuring Dimmer Switches: Load Types & Curve Settings', 'إعداد مفاتيح التعتيم: أنواع الأحمال ومنحنيات الإضاءة', 'Dimmer switches behave differently depending on the load connected — incandescent, LED, or electronic-transformer halogen loads each need a matching dimming curve to avoid flicker or premature bulb failure. Most dimmer curve settings offer trailing-edge or leading-edge dimming; LED loads generally perform best with trailing-edge. Installers should also set a sensible minimum brightness floor so the dimmer doesn''t flicker or cut out at low levels, and confirm the dimmer''s rated wattage comfortably covers the connected load with headroom for future bulb changes.', 'تتصرف مفاتيح التعتيم بشكل مختلف حسب الحمل المتصل — الإضاءة المتوهجة أو LED أو الهالوجين بمحول إلكتروني تحتاج جميعها منحنى تعتيم مطابقًا لتفادي الوميض أو تلف المصباح المبكر. تقدم معظم إعدادات منحنى التعتيم تعتيم الحافة الخلفية أو الأمامية؛ أحمال LED عادة تعمل بأفضل شكل مع الحافة الخلفية. يجب على الفني أيضًا ضبط حد أدنى معقول للسطوع حتى لا يومض المفتاح أو ينطفئ عند المستويات المنخفضة، والتأكد أن قدرة المفتاح المصنفة تغطي الحمل المتصل بهامش أمان لتغييرات المصابيح المستقبلية.', 2 FROM public.modules WHERE slug = 'sonoff-device-specific-mastery';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Air Quality Monitoring: Setting Up Environmental Sensors', 'مراقبة جودة الهواء: إعداد أجهزة استشعار البيئة', 'Environmental air-quality sensors typically monitor several readings at once — CO2, VOC (volatile organic compounds), temperature, and humidity — and translate them into a simple quality indicator for the end user. Installers should mount these sensors away from direct airflow (vents, open windows) which can skew readings, calibrate the baseline reading during an initial settling period after power-on, and set alert thresholds that match the customer''s sensitivity (a nursery or home office often wants tighter thresholds than a garage).', 'تراقب أجهزة استشعار جودة الهواء البيئية عادة عدة قراءات في آن واحد — ثاني أكسيد الكربون والمركبات العضوية المتطايرة ودرجة الحرارة والرطوبة — وتترجمها إلى مؤشر جودة بسيط للمستخدم النهائي. يجب على الفني تركيب هذه الحساسات بعيدًا عن تيار الهواء المباشر (الفتحات، النوافذ المفتوحة) التي قد تشوّه القراءات، ومعايرة القراءة الأساسية خلال فترة استقرار أولية بعد التشغيل، وضبط عتبات التنبيه بما يناسب حساسية العميل (غرفة أطفال أو مكتب منزلي غالبًا تحتاج عتبات أدق من الجراج).', 3 FROM public.modules WHERE slug = 'sonoff-device-specific-mastery';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Building a Smart Thermostat with a Multi-Function Control Panel', 'بناء ترموستات ذكي بلوحة تحكم متعددة الوظائف', 'A wall-mounted control panel used as a smart thermostat typically integrates a touchscreen with relay outputs for HVAC control and optional zone sensors. Installation requires confirming the HVAC system''s control wiring (heat, cool, fan, common) matches the panel''s terminal layout before connecting, setting up temperature scheduling that reflects the household''s daily routine, and pairing any remote temperature sensors used for multi-zone comfort. A correctly configured panel should fail safe — defaulting to a known-safe HVAC state if it loses network connectivity, rather than leaving the system in an undefined state.', 'لوحة التحكم الحائطية متعددة الوظائف المستخدمة كترموستات ذكي تدمج عادة شاشة لمس مع مخارج ريليه للتحكم بنظام التكييف وحساسات مناطق اختيارية. يتطلب التركيب التأكد من أن توصيلات تحكم نظام التكييف (تدفئة، تبريد، مروحة، مشترك) تطابق تخطيط أطراف اللوحة قبل التوصيل، وإعداد جدولة حرارة تعكس الروتين اليومي للمنزل، وإقران أي حساسات حرارة عن بعد تُستخدم لراحة المناطق المتعددة. اللوحة المُعدة بشكل صحيح يجب أن تفشل بأمان — أي تعود إلى حالة تكييف آمنة معروفة عند فقدان اتصال الشبكة، لا أن تترك النظام في حالة غير محددة.', 4 FROM public.modules WHERE slug = 'sonoff-device-specific-mastery';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Flashing a Zigbee USB Coordinator (Dongle)', 'برمجة منسق Zigbee USB (الدونجل)', 'A Zigbee USB coordinator lets a computer or single-board server act as the Zigbee network''s controller, commonly used with self-hosted automation platforms. Flashing custom firmware onto a coordinator dongle involves putting the chip into bootloader/flash mode (often via a physical jumper or button sequence), using vendor-approved flashing tools rather than unofficial third-party binaries, and verifying the flashed firmware version matches what the target automation platform expects before rejoining any devices to the network. Always back up the network''s PAN ID and encryption key before reflashing, since a firmware change can force every paired device to be re-joined manually.', 'يتيح منسق Zigbee USB لجهاز كمبيوتر أو خادم أحادي اللوحة العمل كوحدة تحكم لشبكة Zigbee، ويُستخدم غالبًا مع منصات الأتمتة ذاتية الاستضافة. برمجة برنامج ثابت مخصص على منسق الدونجل تشمل وضع الشريحة في وضع الإقلاع/البرمجة (غالبًا عبر جسر مادي أو تسلسل أزرار)، واستخدام أدوات برمجة معتمدة من المورّد بدلًا من ملفات ثنائية غير رسمية من طرف ثالث، والتحقق من أن إصدار البرنامج الثابت المبرمج يطابق ما تتوقعه منصة الأتمتة المستهدفة قبل إعادة ضم أي أجهزة للشبكة. احفظ دائمًا نسخة احتياطية من معرف الشبكة (PAN ID) ومفتاح التشفير قبل إعادة البرمجة، لأن تغيير البرنامج الثابت قد يجبر كل جهاز مقترن على إعادة الانضمام يدويًا.', 5 FROM public.modules WHERE slug = 'sonoff-device-specific-mastery';
INSERT INTO public.lessons (module_id, title, title_ar, content, content_ar, position) SELECT id, 'Integrating with Apple Home (HomeKit)', 'الدمج مع Apple Home (HomeKit)', 'Bringing devices into Apple''s Home ecosystem requires either native HomeKit compatibility, a Matter bridge, or a third-party bridge exposing devices as HomeKit accessories. Installers should verify accessory categories map correctly (a dimmer should appear as a dimmable light, not a plain switch, so Siri and the Home app expose the right controls), set up rooms and scenes that mirror how the household actually uses each space, and test automations that depend on presence detection, since HomeKit''s geofencing behavior can differ from other ecosystems'' implementations.', 'إدخال الأجهزة إلى منظومة Apple Home يتطلب إما توافقًا أصليًا مع HomeKit، أو جسر Matter، أو جسر طرف ثالث يعرض الأجهزة كإكسسوارات HomeKit. يجب على الفني التحقق من أن فئات الإكسسوار مطابقة بشكل صحيح (يجب أن يظهر المفتاح القابل للتعتيم كإضاءة قابلة للتعتيم، لا كمفتاح عادي، حتى يعرض Siri وتطبيق Home عناصر التحكم الصحيحة)، وإعداد الغرف والمشاهد التي تعكس كيفية استخدام الأسرة الفعلي لكل مساحة، واختبار الأتمتة التي تعتمد على كشف الحضور، لأن سلوك السياج الجغرافي في HomeKit قد يختلف عن تطبيقات المنظومات الأخرى.', 6 FROM public.modules WHERE slug = 'sonoff-device-specific-mastery';
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'bronze', title || ' — Bronze Quiz', title_ar || ' — اختبار برونزي', 80 FROM public.modules WHERE slug = 'sonoff-device-specific-mastery';
INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT q.id, 'Why should you use a non-contact voltage tester before touching any conductor during a retrofit?', 'لماذا يجب استخدام جهاز اختبار جهد بلا تلامس قبل لمس أي موصل أثناء التركيب في تمديدات قائمة؟', 1 FROM public.quizzes q JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-device-specific-mastery' AND q.tier = 'bronze';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'To re-verify the circuit is actually de-energized after switching off the breaker', 'لإعادة التحقق من انقطاع التيار فعليًا بعد إيقاف القاطع', TRUE, 1 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-device-specific-mastery' AND q.tier = 'bronze' AND qq.question = 'Why should you use a non-contact voltage tester before touching any conductor during a retrofit?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'To measure the color temperature of the wiring', 'لقياس درجة حرارة لون الأسلاك', FALSE, 2 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-device-specific-mastery' AND q.tier = 'bronze' AND qq.question = 'Why should you use a non-contact voltage tester before touching any conductor during a retrofit?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'It is only needed for Zigbee devices', 'يُحتاج فقط لأجهزة Zigbee', FALSE, 3 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-device-specific-mastery' AND q.tier = 'bronze' AND qq.question = 'Why should you use a non-contact voltage tester before touching any conductor during a retrofit?';
INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT q.id, 'Which dimming edge type generally performs best with LED loads?', 'أي نوع حافة تعتيم يعمل عادة بأفضل شكل مع أحمال LED؟', 2 FROM public.quizzes q JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-device-specific-mastery' AND q.tier = 'bronze';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Trailing-edge', 'الحافة الخلفية', TRUE, 1 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-device-specific-mastery' AND q.tier = 'bronze' AND qq.question = 'Which dimming edge type generally performs best with LED loads?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Leading-edge only, always', 'الحافة الأمامية فقط دائمًا', FALSE, 2 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-device-specific-mastery' AND q.tier = 'bronze' AND qq.question = 'Which dimming edge type generally performs best with LED loads?';
INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Dimming type has no effect on LEDs', 'نوع التعتيم لا يؤثر على LED', FALSE, 3 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-device-specific-mastery' AND q.tier = 'bronze' AND qq.question = 'Which dimming edge type generally performs best with LED loads?';
